 b.hp=math.max(0,b.hp-damage);b.stun=blocked and 8 or s.stun;b.guardStun=blocked;b.flash=blocked and 0 or 7;b.attack=nil;b.x=clamp(b.x+a.face*(blocked and 10 or (airFollow and s.push*.45 or s.push)),-535,535)
